    <style>
        :root{--bg:#f7f7f5;--surface:#fff;--surface-2:#f1f1ef;--ink:#171717;--muted:#6b6b67;--line:#deded8;--brand:#111;--focus:#7c3aed;--shadow-sm:0 1px 2px rgba(0,0,0,.04);--shadow-md:0 12px 36px rgba(0,0,0,.07);--radius-sm:10px;--radius-md:16px;--radius-lg:24px}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font-family:Inter,Tahoma,Arial,sans-serif;-webkit-font-smoothing:antialiased}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}.container{width:min(1220px,calc(100% - 40px));margin:auto}.site-header{position:sticky;top:0;z-index:100;background:rgba(255,255,255,.88);backdrop-filter:blur(16px);border-bottom:1px solid rgba(222,222,216,.9)}.header-inner{min-height:72px;display:flex;align-items:center;justify-content:space-between;gap:24px}.brand{display:inline-flex;align-items:center;gap:10px;font-size:20px;font-weight:900;letter-spacing:-.4px}.brand-mark{width:34px;height:34px;border-radius:10px;background:#111;color:#fff;display:grid;place-items:center;font-size:14px}.main-nav{display:flex;align-items:center;gap:4px}.main-nav a,.main-nav button{border:0;background:transparent;padding:9px 12px;border-radius:9px;color:#4d4d49;cursor:pointer}.main-nav a:hover,.main-nav button:hover{background:var(--surface-2);color:#111}.header-actions{display:flex;align-items:center;gap:8px}.wallet-chip{padding:9px 12px;background:#111;color:#fff;border-radius:999px;font-size:12px;font-weight:800}.cart-chip{display:inline-flex;align-items:center;gap:6px}.cart-count{min-width:20px;height:20px;padding:0 6px;border-radius:999px;background:#7c3aed;color:#fff;display:inline-grid;place-items:center;font-size:11px}.page{min-height:calc(100vh - 160px)}.hero{padding:52px 0 24px}.hero-card{position:relative;overflow:hidden;border:1px solid #242424;background:#111;color:#fff;border-radius:28px;padding:64px;box-shadow:var(--shadow-md)}.hero-card:before{content:"";position:absolute;inset:auto -10% -55% auto;width:480px;height:480px;border-radius:50%;background:radial-gradient(circle,rgba(124,58,237,.34),transparent 68%)}.hero-card:after{content:"";position:absolute;inset:-55% auto auto -8%;width:380px;height:380px;border-radius:50%;background:radial-gradient(circle,rgba(255,255,255,.08),transparent 68%)}.eyebrow{position:relative;z-index:1;display:inline-flex;align-items:center;padding:7px 11px;border:1px solid #333;border-radius:999px;color:#cfcfca;font-size:12px;font-weight:700}.hero h1{position:relative;z-index:1;max-width:780px;margin:18px 0 16px;font-size:clamp(38px,5.4vw,68px);line-height:1.08;letter-spacing:-2.6px}.hero p{position:relative;z-index:1;max-width:680px;margin:0 0 28px;color:#b8b8b3;line-height:2;font-size:16px}.hero-actions{position:relative;z-index:1;display:flex;flex-wrap:wrap;gap:10px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:44px;padding:0 16px;border:1px solid var(--line);border-radius:11px;font-weight:800;cursor:pointer;transition:.18s}.btn:hover{transform:translateY(-1px)}.btn-primary{background:#111;color:#fff;border-color:#111}.btn-light{background:#fff;color:#111;border-color:#fff}.btn-soft{background:#f5f5f2;color:#222;border-color:#e8e8e2}.btn-ghost{background:transparent}.section{padding:28px 0 44px}.section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin-bottom:18px}.section-title{display:flex;flex-direction:column;gap:5px}.section-head h2{margin:0;font-size:26px;letter-spacing:-.8px}.section-head p{margin:0;color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}.card{background:var(--surface);border:1px solid var(--line);border-radius:18px;box-shadow:var(--shadow-sm)}.card-link{display:block;transition:.2s}.card-link:hover{transform:translateY(-3px);box-shadow:var(--shadow-md)}.category-card{min-height:132px;padding:18px;display:flex;flex-direction:column;justify-content:space-between;background:linear-g