ign:center;background:#fff;border:1px dashed #d4d4cc;border-radius:18px;color:var(--muted)}.stats-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.stat-card{padding:20px}.stat-label{color:var(--muted);font-size:12px}.stat-value{margin-top:8px;font-size:30px;font-weight:900;letter-spacing:-1px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:16px;background:#fff}.table-wrap table{width:100%;border-collapse:collapse;min-width:650px}.table-wrap th,.table-wrap td{padding:14px;border-bottom:1px solid #ededE7;text-align:right;font-size:13px}.table-wrap th{background:#fafaf8;color:#66665f}.table-wrap tr:last-child td{border-bottom:0}.footer{padding:36px 0 44px;color:#999991;text-align:center;font-size:12px}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}.main-nav{display:none}.stats-grid{grid-template-columns:1fr}.hero-card{padding:48px}}@media(max-width:620px){.container{width:calc(100% - 24px)}.header-inner{min-height:64px}.header-actions .wallet-chip{display:none}.hero{padding-top:24px}.hero-card{padding:32px 22px;border-radius:22px}.hero h1{font-size:38px;letter-spacing:-1.7px}.hero p{font-size:14px}.grid{grid-template-columns:1fr}.section{padding-bottom:30px}.form-box{margin:30px auto;padding:22px}.product-image{height:220px}.section-head{align-items:flex-start;flex-direction:column}}
